package server

import (
	"chatapp/backend/cache"
	"chatapp/backend/config"
	"chatapp/backend/datapool"
	"chatapp/backend/log"
	"chatapp/backend/model"
	"chatapp/backend/protocal"
	"chatapp/backend/service"
	"errors"
	"sync"

	"github.com/gogo/protobuf/proto"
	"github.com/google/uuid"
)

var AppServer = NewServer()

type Server struct {
	Clients    map[string]*ClientWs
	mutex      *sync.Mutex
	Broadcast  chan []byte
	Register   chan *ClientWs
	Unregister chan *ClientWs
}

func NewServer() *Server {
	return &Server{
		mutex:      &sync.Mutex{},
		Clients:    make(map[string]*ClientWs),
		Broadcast:  make(chan []byte, 512),
		Register:   make(chan *ClientWs, 64),
		Unregister: make(chan *ClientWs, 64),
	}
}

// ConsumerKafkaMsg 消费 kafka 后转入应用内广播通道
func ConsumerKafkaMsg(data []byte) {
	AppServer.Broadcast <- data
}

func (s *Server) Start() {
	log.Logger.Info("start server", log.Any("start server", "start server..."))
	for {
		select {
		case clientConn := <-s.Register:
			log.Logger.Info("login", log.Any("login", "new user login in "+clientConn.Name))
			// 同名用户重新连接时，先关闭旧连接
			if old, ok := s.Clients[clientConn.Name]; ok {
				close(old.Send)
				delete(s.Clients, clientConn.Name)
			}
			s.Clients[clientConn.Name] = clientConn
			if err := cache.MarkUserOnline(clientConn.Name); err != nil {
				log.Logger.Warn("mark user online failed", log.String("user", clientConn.Name), log.Any("error", err))
			}
			welcome := &protocol.Message{
				From:    "System",
				To:      clientConn.Name,
				Content: "welcome!",
			}
			if protoMsg, err := proto.Marshal(welcome); err == nil {
				clientConn.Send <- protoMsg
			}

		case clientConn := <-s.Unregister:
			log.Logger.Info("logout", log.Any("logout", clientConn.Name))
			if _, ok := s.Clients[clientConn.Name]; ok {
				close(clientConn.Send)
				delete(s.Clients, clientConn.Name)
			}
			if err := cache.MarkUserOffline(clientConn.Name); err != nil {
				log.Logger.Warn("mark user offline failed", log.String("user", clientConn.Name), log.Any("error", err))
			}

		case message := <-s.Broadcast:
			msg := &protocol.Message{}
			if err := proto.Unmarshal(message, msg); err != nil {
				log.Logger.Error("unmarshal broadcast message failed", log.Any("error", err))
				continue
			}

			if msg.To != "" {
				// 普通消息（文本、文件、图片、音视频文件）：存储 + 转发
				if msg.ContentType >= config.TEXT && msg.ContentType <= config.VIDEO {
					if _, exists := s.Clients[msg.From]; exists {
						if err := saveMessage(msg); err != nil {
							log.Logger.Error("save message failed", log.Any("error", err))
						}
					}

					switch msg.MessageType {
					case config.MESSAGE_TYPE_GROUP:
						s.sendGroupMessage(msg)
					default:
						s.sendUserMessage(msg)
					}
				} else {
					// 通话信令类消息（例如语音/视频通话）：只转发，不存储
					s.sendRawMessage(msg.To, message)
				}
				continue
			}

			// 未指定接收方，进行广播
			for id, conn := range s.Clients {
				log.Logger.Info("allUser", log.Any("allUser", id))
				select {
				case conn.Send <- message:
				default:
					close(conn.Send)
					delete(s.Clients, conn.Name)
				}
			}
		}
	}
}

func (s *Server) sendRawMessage(to string, payload []byte) {
	client, ok := s.Clients[to]
	if !ok {
		return
	}
	select {
	case client.Send <- payload:
	default:
		close(client.Send)
		delete(s.Clients, client.Name)
	}
}

func (s *Server) sendUserMessage(msg *protocol.Message) {
	if msg == nil {
		return
	}
	client, ok := s.Clients[msg.To]
	if !ok {
		return
	}
	msgByte, err := proto.Marshal(msg)
	if err != nil {
		log.Logger.Error("marshal user message failed", log.Any("error", err))
		return
	}
	select {
	case client.Send <- msgByte:
	default:
		close(client.Send)
		delete(s.Clients, client.Name)
	}
}

func (s *Server) sendGroupMessage(msg *protocol.Message) {
	if msg == nil {
		return
	}
	members := service.GroupService.GetGroupMembers(msg.To)
	if len(members) == 0 {
		return
	}

	for _, user := range members {
		if user.Uuid == msg.From {
			continue
		}
		client, ok := s.Clients[user.Uuid]
		if !ok {
			continue
		}

		msgSend := *msg
		msgSend.To = user.Uuid

		msgByte, err := proto.Marshal(&msgSend)
		if err != nil {
			log.Logger.Error("marshal group message failed", log.Any("error", err))
			continue
		}

		select {
		case client.Send <- msgByte:
		default:
			close(client.Send)
			delete(s.Clients, client.Name)
		}
	}
}

func saveMessage(message *protocol.Message) error {
	if message == nil {
		return errors.New("message is nil")
	}
	if message.From == "" || message.To == "" {
		return errors.New("message.from or message.to is empty")
	}

	content := message.Content
	if content == "" && message.Url != "" {
		// 对于文件消息，至少保留一个可追踪内容（URL）
		content = message.Url
	}

	msgType := config.MESSAGE_TYPE_USER
	if message.MessageType == config.MESSAGE_TYPE_GROUP {
		msgType = config.MESSAGE_TYPE_GROUP
	}

	dbMessage := model.Message{
		Uuid:     uuid.New().String(),
		FromUser: message.From,
		ToTarget: message.To,
		Content:  content,
		MsgType:  msgType,
		IsRead:   false,
	}

	return datapool.GetDB().Create(&dbMessage).Error
}

package kafka

import (
	"chatapp/backend/log"
	"errors"
)

func Send(data []byte) error {
	if len(data) == 0 {
		return errors.New("kafka payload is empty")
	}

	consumerMu.RLock()
	callback := consumerCallback
	consumerMu.RUnlock()

	if callback == nil {
		return errors.New("kafka consumer callback is not initialized")
	}

	callback(data)
	return nil
}

func InitProducer(topic string, hosts []string) {
	log.Logger.Info(
		"init kafka producer (in-memory fallback)",
		log.String("topic", topic),
		log.Any("hosts", hosts),
	)
}

