package handlers

import (
	"chatapp/backend/cache"
	"chatapp/backend/log"
	"chatapp/backend/model"
	"chatapp/backend/service"
	"net/http"
	"strings"

	"github.com/google/uuid"
	"github.com/gin-gonic/gin"
	"go.uber.org/zap"
)

func GetUserDetails(c *gin.Context) {
	userUUID := strings.TrimSpace(c.Param("uuid"))
	if userUUID == "" {
		c.JSON(http.StatusOK, model.FailMsg("uuid 不能为空"))
		return
	}

	user := service.UserService.GetUserDetails(userUUID)
	if user == nil {
		c.JSON(http.StatusOK, model.FailMsg("用户不存在"))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg(user))
}

// 通过用户名获取用户信息
func GetUserByName(c *gin.Context) {
	name := strings.TrimSpace(c.Query("name"))
	if name == "" {
		c.JSON(http.StatusOK, model.FailMsg("name 不能为空"))
		return
	}

	user := service.UserService.GetUserByName(name)
	if user == nil {
		c.JSON(http.StatusOK, model.FailMsg("用户不存在"))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg(user))
}

func GetGroupByName(c *gin.Context) {
	name := strings.TrimSpace(c.Query("name"))
	if name == "" {
		c.JSON(http.StatusOK, model.FailMsg("name 不能为空"))
		return
	}

	group := service.GroupService.GetGroupByName(name)
	if group == nil {
		c.JSON(http.StatusOK, model.FailMsg("群组不存在"))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg(group))
}

func Register(c *gin.Context) {
	var user model.User
	if err := c.ShouldBindJSON(&user); err != nil {
		log.Logger.Error("Register bind json error", zap.Error(err))
		c.JSON(http.StatusOK, model.FailMsg("参数绑定失败"))
		return
	}
	err := service.UserService.Register(&user)
	if err != nil {
		c.JSON(http.StatusOK, model.FailMsg(err.Error()))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg(user))
}

func Login(c *gin.Context) {
	var user model.User
	if err := c.ShouldBindJSON(&user); err != nil {
		log.Logger.Error("Login bind json error", zap.Error(err))
		c.JSON(http.StatusOK, model.FailMsg("参数绑定失败"))
		return
	}
	log.Logger.Debug("user", log.Any("user", user))

	allowed, attemptCount, limitErr := cache.CheckLoginRateLimit(c.ClientIP(), user.Username)
	if limitErr != nil {
		log.Logger.Warn("redis login limit check failed", log.Any("error", limitErr))
	}
	if !allowed {
		c.JSON(http.StatusOK, model.FailMsg(cache.BuildLoginRateLimitMessage(attemptCount)))
		return
	}

	if err := service.UserService.Login(&user); err == nil {
		if resetErr := cache.ResetLoginRateLimit(c.ClientIP(), user.Username); resetErr != nil {
			log.Logger.Warn("redis reset login limit failed", log.Any("error", resetErr))
		}
		c.JSON(http.StatusOK, model.SuccessMsg(user))
		return
	}

	c.JSON(http.StatusOK, model.FailMsg("登录失败"))
}

func CreateGroup(c *gin.Context) {
	var newGroup model.Group
	if err := c.ShouldBindJSON(&newGroup); err != nil {
		log.Logger.Error("CreateGroup bind json error", zap.Error(err))
		c.JSON(http.StatusOK, model.FailMsg("参数绑定失败"))
		return
	}
	log.Logger.Debug("newGroup", log.Any("newGroup", newGroup))
	newGroup.Name = strings.TrimSpace(newGroup.Name)
	if newGroup.Name == "" {
		c.JSON(http.StatusOK, model.FailMsg("群组名称不能为空"))
		return
	}

	newGroup.Uuid = uuid.New().String()

	err := service.GroupService.CreateGroup(&newGroup)
	if err != nil {
		c.JSON(http.StatusOK, model.FailMsg(err.Error()))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg(newGroup))
}

func JoinGroup(c *gin.Context) {
	groupId := strings.TrimSpace(c.Param("groupUuid"))
	userId := strings.TrimSpace(c.Param("userUuid"))
	if groupId == "" || userId == "" {
		c.JSON(http.StatusOK, model.FailMsg("groupUuid 或 userUuid 不能为空"))
		return
	}

	log.Logger.Debug("JoinGroup", log.Any("groupId", groupId), log.Any("userId", userId))

	// service.JoinGroup expects (groupUuid, userUuid)
	err := service.GroupService.JoinGroup(groupId, userId)
	if err != nil {
		c.JSON(http.StatusOK, model.FailMsg(err.Error()))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg("加入群聊成功"))
}

func GetGroupHistoryMessage(c *gin.Context) {
	groupUuid := strings.TrimSpace(c.Param("groupUuid"))
	if groupUuid == "" {
		c.JSON(http.StatusOK, model.FailMsg("groupUuid 不能为空"))
		return
	}
	log.Logger.Debug("GetGroupHistoryMessage", log.Any("groupUuid", groupUuid))
	c.JSON(http.StatusOK, model.SuccessMsg(service.GroupService.GetGroupHistoryMessage(groupUuid)))
}

func AddFriend(c *gin.Context) {
	var friendRequest model.FriendRequest
	if err := c.ShouldBindJSON(&friendRequest); err != nil {
		log.Logger.Error("AddFriend bind json error", zap.Error(err))
		c.JSON(http.StatusOK, model.FailMsg("参数绑定失败"))
		return
	}
	log.Logger.Debug("friendRequest", log.Any("friendRequest", friendRequest))

	err := service.UserService.AddFriend(&friendRequest)
	if err != nil {
		c.JSON(http.StatusOK, model.FailMsg(err.Error()))
		return
	}
	c.JSON(http.StatusOK, model.SuccessMsg("添加好友成功"))
}


func GetUserOnlineStatus(c *gin.Context) {
	userUUID := strings.TrimSpace(c.Query("uuid"))
	if userUUID == "" {
		c.JSON(http.StatusOK, model.FailMsg("uuid 不能为空"))
		return
	}

	online, err := cache.IsUserOnline(userUUID)
	if err != nil {
		log.Logger.Warn("get user online status failed", log.String("user", userUUID), log.Any("error", err))
		c.JSON(http.StatusOK, model.FailMsg("查询在线状态失败"))
		return
	}

	c.JSON(http.StatusOK, model.SuccessMsg(map[string]interface{}{
		"uuid":   userUUID,
		"online": online,
	}))
}

func AIChat(c *gin.Context) {
	var req model.LLMChatRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		log.Logger.Error("AIChat bind json error", zap.Error(err))
		c.JSON(http.StatusOK, model.FailMsg("参数绑定失败"))
		return
	}

	req.Message = strings.TrimSpace(req.Message)
	if req.Message == "" {
		c.JSON(http.StatusOK, model.FailMsg("message 不能为空"))
		return
	}

	reply, err := service.LLMService.Chat(&req)
	if err != nil {
		log.Logger.Warn("AIChat failed", log.Any("error", err))
		c.JSON(http.StatusOK, model.FailMsg(err.Error()))
		return
	}

	c.JSON(http.StatusOK, model.SuccessMsg(map[string]interface{}{
		"reply": reply,
	}))
}

